WITH cleaned AS (SELECT *, CEIL(rating) AS rating_whole, COALESCE(city, 'OTHER') AS city_filled FROM suppliers WHERE supplier_name IS NOT NULL) SELECT CASE WHEN rating_whole >= 85 THEN 'LARGE' ELSE 'SMALL' END AS rating_whole_tier, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN city = 'New York' THEN 1 END), 0), 2) AS rating_per_new_york, PERCENTILE_APPROX(rating_whole, 0.95) AS rating_whole_p95, SIZE(COLLECT_SET(city)) AS num_cities, SIZE(COLLECT_SET(country)) AS num_countries, APPROX_PERCENTILE(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles FROM cleaned GROUP BY CASE WHEN rating_whole >= 85 THEN 'LARGE' ELSE 'SMALL' END ORDER BY rating_whole_p95 NULLS FIRST;
